<?php
require_once __DIR__.'/verification_views.php';
function handleAction(): void {
 global $warnings,$warningPayload,$importPreview,$error;checkCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='logout'){$_SESSION=[];session_destroy();redirect('login');}
 if($action==='user_save'){requireAdmin();$uid=(int)($_POST['user_id']??0);$u=need('users',$uid);$username=textValue($_POST['username']??'','Usuario',80);$name=textValue($_POST['driver_name']??'','Nombre del conductor',150);$lic=textValue($_POST['license_number']??'','Número de licencia',80);$exp=dateValue($_POST['license_expires']??'','Vencimiento');$newPassword=(string)($_POST['password']??'');if($newPassword!==''&&strlen($newPassword)<6)throw new RuntimeException('La nueva contraseña debe tener al menos 6 caracteres.');if($newPassword!=='')execute('UPDATE users SET username=?,driver_name=?,license_number=?,license_expires=?,password_hash=? WHERE id=?',[$username,$name,$lic,$exp,password_hash($newPassword,PASSWORD_DEFAULT),$uid]);else execute('UPDATE users SET username=?,driver_name=?,license_number=?,license_expires=? WHERE id=?',[$username,$name,$lic,$exp,$uid]);flash('Cuenta de usuario actualizada.');redirect('users');}
 if($action==='user_delete_keep'){requireAdmin();$uid=(int)($_POST['user_id']??0);need('users',$uid);db()->beginTransaction();try{execute('UPDATE trips SET user_id=NULL WHERE user_id=?',[$uid]);execute('UPDATE reservations SET user_id=NULL WHERE user_id=?',[$uid]);execute('DELETE FROM users WHERE id=?',[$uid]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}flash('Cuenta eliminada; sus registros fueron conservados.');redirect('users');}
 if($action==='user_delete_all'){requireAdmin();$uid=(int)($_POST['user_id']??0);need('users',$uid);db()->beginTransaction();try{execute('DELETE FROM reservations WHERE user_id=?',[$uid]);execute('DELETE FROM trips WHERE user_id=?',[$uid]);execute('DELETE FROM users WHERE id=?',[$uid]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}flash('Cuenta y registros del usuario eliminados.');redirect('users');}
 if($action==='profile_save'){if(!isExternal())throw new RuntimeException('Sesión de usuario requerida.');$name=textValue($_POST['driver_name']??'','Nombre',150);$lic=textValue($_POST['license_number']??'','Número de licencia',80);$exp=dateValue($_POST['license_expires']??'','Vencimiento');execute('UPDATE users SET driver_name=?,license_number=?,license_expires=? WHERE id=?',[$name,$lic,$exp,currentUserId()]);flash('Perfil de conductor actualizado.');redirect('profile');}
