 if($action==='vehicle_save'){requireAdmin();$v=['brand'=>textValue($_POST['brand']??'','Marca',80),'model'=>textValue($_POST['model']??'','Modelo',100),'model_year'=>(int)($_POST['model_year']??0),'plates'=>strtoupper(textValue($_POST['plates']??'','Placas',30)),'economic_number'=>textValue($_POST['economic_number']??'','No. económico',30),'responsible'=>textValue($_POST['responsible']??'','Responsable',150),'department'=>textValue($_POST['department']??'','Departamento',150),'baseline_date'=>dateValue($_POST['baseline_date']??'','Fecha de referencia'),'baseline_km'=>integerValue($_POST['baseline_km']??'','Km de referencia'),'verification_permit'=>!empty($_POST['verification_permit'])?1:0];if($v['model_year']<1900||$v['model_year']>2100)throw new RuntimeException('Año de modelo inválido.');if($id){execute('UPDATE vehicles SET brand=?,model=?,model_year=?,plates=?,economic_number=?,responsible=?,department=?,baseline_date=?,baseline_km=?,verification_permit=? WHERE id=?',[...array_values($v),$id]);}else{execute('INSERT INTO vehicles(brand,model,model_year,plates,economic_number,responsible,department,baseline_date,baseline_km,verification_permit) VALUES (?,?,?,?,?,?,?,?,?,?)',array_values($v));$id=(int)db()->lastInsertId();}flash('Vehículo guardado.');redirect('vehicle',['id'=>$id]);}
 if($action==='trip_save'){
  $pending=pendingTrip();$confirmPending=!empty($_POST['confirm_pending']);
  if($confirmPending&&$pending){
   if(!hash_equals((string)$pending['token'],(string)($_POST['warning_token']??'')))throw new RuntimeException('La confirmación de advertencias venció. Captura nuevamente la bitácora.');
   $id=(int)$pending['id'];$old=$id?need('trips',$id):null;if($old&&!canEditTrip($old))throw new RuntimeException('Solo puedes editar tus propios registros.');if(isExternal())assertLicenseValid();
   $t=$pending['data'];
  }else{
   clearPendingTrip();$old=$id?need('trips',$id):null;if($old&&!canEditTrip($old))throw new RuntimeException('Solo puedes editar tus propios registros.');if(isExternal())assertLicenseValid();$t=normalizeTripForm($_POST);if(isExternal()){$u=currentUser();$t['driver']=$u['driver_name'];}
  }
  $vehicle=need('vehicles',$t['vehicle_id']);$others=rows('SELECT * FROM trips WHERE vehicle_id=? AND id<>? ORDER BY departure_at,id',[$t['vehicle_id'],$id]);$blocking=tripBlockingConflicts($t,$others);if($blocking)throw new RuntimeException('No se puede registrar la bitácora por conflictos: '.implode(' ',$blocking));$periods=rows('SELECT * FROM inactive_periods WHERE vehicle_id=?',[$t['vehicle_id']]);if(isExternal()&&periodForDate($periods,$t['request_date']))throw new RuntimeException('No puedes registrar una bitácora: el vehículo está en un periodo de inactividad definido por el administrador.');$warnings=tripWarnings($t,$others,$vehicle,$periods);$warningPayload=[$t,$id];
