    redirect('trip_form',['id'=>$id,'vehicle_id'=>$t['vehicle_id'],'pending'=>1]);
   }
  }else{clearPendingTrip();}
  if($id){execute('UPDATE trips SET vehicle_id=?,request_date=?,departure_at=?,arrival_at=?,km_start=?,km_end=?,driver=?,purpose=?,requester=?,observations=?,version=version+1 WHERE id=?',[...array_values($t),$id]);remember($t);}else $id=createTrip($t,keygen(),isExternal()?currentUserId():null);flash('Bitácora #'.$id.' guardada.');redirect('trip',['id'=>$id]);
 }
 if($action==='trip_delete'){requireAdmin();$t=need('trips',$id);execute('DELETE FROM trips WHERE id=?',[$id]);flash('Bitácora eliminada.');redirect('vehicle',['id'=>$t['vehicle_id']]);}
 if($action==='fuel_save'||$action==='fuel_delete'){requireAdmin();if($action==='fuel_delete'){execute('DELETE FROM fuel_loads WHERE id=?',[$id]);flash('Carga eliminada.');redirect('fuel');}$f=normalizeFuel($_POST);if($id)execute('UPDATE fuel_loads SET vehicle_id=?,fuel_date=?,liters=?,amount=?,payment_method=?,card_last5=?,version=version+1 WHERE id=?',[...array_values($f),$id]);else createFuel($f,keygen());flash('Carga de gasolina guardada.');redirect('fuel');}
 if($action==='period_save'||$action==='period_delete'){requireAdmin();$vid=(int)($_POST['vehicle_id']??0);if($action==='period_delete'){execute('DELETE FROM inactive_periods WHERE id=?',[$id]);flash('Periodo eliminado.');redirect('vehicle',['id'=>$vid]);}$a=dateValue($_POST['start_date']??'','Inicio');$b=trim($_POST['end_date']??'')!==''?dateValue($_POST['end_date'],'Fin'):null;$reason=$_POST['reason']??'';if(!in_array($reason,['DESCOMPUESTO Y EN LAS INSTALACIONES DEL IMPLAN','RECIBIENDO SERVICIO EN EL TALLER MECÁNICO','NO DISPONIBLE'],true))throw new RuntimeException('Estado inválido.');if($id)execute('UPDATE inactive_periods SET start_date=?,end_date=?,reason=?,notes=?,version=version+1 WHERE id=?',[$a,$b,$reason,mb_strtoupper(trim((string)$_POST['notes']),'UTF-8'),$id]);else execute('INSERT INTO inactive_periods(vehicle_id,start_date,end_date,reason,notes) VALUES (?,?,?,?,?)',[$vid,$a,$b,$reason,mb_strtoupper(trim((string)$_POST['notes']),'UTF-8')]);flash('Periodo guardado.');redirect('vehicle',['id'=>$vid]);}
 if($action==='import_preview'){requireAdmin();$file=$_FILES['xlsx']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK)throw new RuntimeException('No se recibió el XLSX.');$batch=parseImport($file['tmp_name']);$importPreview=evaluateImport($batch);$_SESSION['import_batch']=$batch;$_SESSION['import_review']=$importPreview;return;}
 if($action==='import_commit'){requireAdmin();$batch=$_SESSION['import_batch']??null;if(!$batch)throw new RuntimeException('Primero revisa un archivo.');$result=evaluateImport($batch,true);unset($_SESSION['import_batch'],$_SESSION['import_review']);flash('Importación completa: '.$result['trips'].' bitácoras y '.$result['fuel'].' cargas.');redirect('import');}
 throw new RuntimeException('Acción no encontrada.');
